    cursor: pointer;
    border-bottom: 1px solid #f0f0f0;
    position: relative;
    transition: background 0.15s;
}

.channel-item:hover {
    background: #e9ecef;
}

.channel-item.active {
    background: #d4e5ff;
    border-left: 3px solid #0066cc;
}

.channel-name {
