+    margin: 0;
+    font-size: 1rem;
+    font-weight: 700;
+}
+
+.close-btn {
+    background: none;
+    border: none;
+    font-size: 1.2rem;
+    cursor: pointer;
+    color: #666;
+    padding: 0.25rem 0.5rem;
+    border-radius: 4px;
+}
+
+.close-btn:hover {
+    background: #f0f0f0;
+    color: #333;
+}
+
+.thread-root-message {
+    padding: 0.75rem 1rem;
+    background: #f8f9fa;
+    border-bottom: 1px solid #e0e0e0;
+}
+
+.thread-divider {
+    padding: 0.5rem 1rem;
+    font-size: 0.75rem;
+    color: #888;
+    border-bottom: 1px solid #f0f0f0;
+}
+
+.thread-replies {
+    flex: 1;
+    overflow-y: auto;
+    padding: 0.5rem 1rem;
+}
+
+.thread-reply {
+    padding: 0.5rem 0;
+    border-bottom: 1px solid #f8f8f8;
+}
